CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'viewer' CHECK (role IN ('admin','operator','viewer'));
ALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_secret TEXT;
CREATE TABLE IF NOT EXISTS user_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS user_sessions_active_idx ON user_sessions(user_id, expires_at DESC) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT UNIQUE NOT NULL, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS password_reset_tokens_active_idx ON password_reset_tokens(user_id, expires_at DESC) WHERE used_at IS NULL;
CREATE TABLE IF NOT EXISTS mfa_recovery_codes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, code_hash TEXT UNIQUE NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users(id) ON DELETE SET NULL, actor_email TEXT NOT NULL DEFAULT 'system', action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, summary TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_events_created_idx ON audit_events(created_at DESC);
CREATE TABLE IF NOT EXISTS targets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, base_url TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('rest','graphql')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE targets ADD COLUMN IF NOT EXISTS schedule_interval_seconds INTEGER NOT NULL DEFAULT 0 CHECK (schedule_interval_seconds = 0 OR schedule_interval_seconds >= 30);
CREATE TABLE IF NOT EXISTS probe_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_id UUID NOT NULL REFERENCES targets(id) ON DELETE CASCADE, triggered_by TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, overall_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS probe_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID NOT NULL REFERENCES probe_runs(id) ON DELETE CASCADE, layer INTEGER NOT NULL CHECK (layer BETWEEN 1 AND 4), status TEXT NOT NULL CHECK (status IN ('pass','fail','skip')), latency_ms INTEGER NOT NULL DEFAULT 0, error_msg TEXT, checked_at TIMESTAMPTZ NOT NULL);
ALTER TABLE probe_results ADD COLUMN IF NOT EXISTS diagnostics JSONB;
CREATE TABLE IF NOT EXISTS deployment_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_id UUID NOT NULL REFERENCES targets(id) ON DELETE CASCADE, version TEXT NOT NULL, deployed_by TEXT, deployed_at TIMESTAMPTZ NOT NULL, source TEXT NOT NULL, delivery_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS incidents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_id UUID NOT NULL REFERENCES targets(id), run_id UUID NOT NULL REFERENCES probe_runs(id), failed_layer INTEGER NOT NULL, attributed_to TEXT NOT NULL, nearest_deploy_id UUID REFERENCES deployment_events(id), deploy_delta_mins INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved'));
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS resolved_at TIMESTAMPTZ;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS failure_count INTEGER NOT NULL DEFAULT 1;
ALTER TABLE incidents DROP CONSTRAINT IF EXISTS incidents_status_check;
ALTER TABLE incidents ADD CONSTRAINT incidents_status_check CHECK (status IN ('open','acknowledged','resolved'));
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS owner TEXT;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS acknowledged_at TIMESTAMPTZ;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS acknowledgement_note TEXT;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS resolution_note TEXT;
CREATE INDEX IF NOT EXISTS probe_runs_target_started_idx ON probe_runs(target_id, started_at DESC);
CREATE INDEX IF NOT EXISTS deployment_events_target_time_idx ON deployment_events(target_id, deployed_at DESC);
CREATE INDEX IF NOT EXISTS incidents_target_time_idx ON incidents(target_id, created_at DESC);
CREATE INDEX IF NOT EXISTS incidents_open_target_layer_idx ON incidents(target_id, failed_layer) WHERE status='open';
CREATE TABLE IF NOT EXISTS alert_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_id UUID NOT NULL REFERENCES targets(id) ON DELETE CASCADE, name TEXT NOT NULL, min_failure_count INTEGER NOT NULL DEFAULT 1 CHECK (min_failure_count > 0), webhook_url TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE alert_rules ADD COLUMN IF NOT EXISTS email_to TEXT;
CREATE TABLE IF NOT EXISTS alert_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_id UUID NOT NULL REFERENCES alert_rules(id) ON DELETE CASCADE, incident_id UUID REFERENCES incidents(id) ON DELETE SET NULL, channel TEXT NOT NULL CHECK (channel IN ('webhook','email')), status TEXT NOT NULL CHECK (status IN ('sent','failed')), attempt INTEGER NOT NULL DEFAULT 1, response_status INTEGER, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS alert_deliveries_rule_created_idx ON alert_deliveries(rule_id, created_at DESC);
CREATE TABLE IF NOT EXISTS slo_targets (target_id UUID PRIMARY KEY REFERENCES targets(id) ON DELETE CASCADE, target_uptime_percent NUMERIC(5,3) NOT NULL CHECK (target_uptime_percent > 0 AND target_uptime_percent < 100), window_hours INTEGER NOT NULL DEFAULT 720 CHECK (window_hours IN (24,168,720)), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS api_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL, target_id UUID REFERENCES targets(id) ON DELETE CASCADE, scopes TEXT[] NOT NULL, expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS api_tokens_active_idx ON api_tokens(token_hash) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS response_baselines (target_id UUID PRIMARY KEY REFERENCES targets(id) ON DELETE CASCADE, shape JSONB NOT NULL, captured_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, key_hash TEXT UNIQUE NOT NULL, last_seen_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE targets ADD COLUMN IF NOT EXISTS agent_id UUID REFERENCES agents(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS transaction_workflows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_id UUID NOT NULL REFERENCES targets(id) ON DELETE CASCADE, name TEXT NOT NULL, steps JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transaction_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id UUID NOT NULL REFERENCES transaction_workflows(id) ON DELETE CASCADE, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL CHECK (status IN ('pass','fail')), results JSONB NOT NULL);
